const crypto = require('crypto');

const item = $input.first();
const headers = item.json.headers || {};
const body = item.json.body;

const signatureHeader = headers['x-wacrm-signature'];
const secret = $env.WACRM_WEBHOOK_SECRET;

if (!signatureHeader) {
  throw new Error('Falta el header x-wacrm-signature');
}

if (!secret) {
  throw new Error('Falta WACRM_WEBHOOK_SECRET');
}

if (!body) {
  throw new Error('No se encontró body');
}

const match = signatureHeader.match(/^t=(\d+),v1=([a-f0-9]+)$/i);

if (!match) {
  throw new Error('Formato de x-wacrm-signature inválido');
}

const timestamp = match[1];
const receivedSignature = match[2];

// Protección contra replay
const now = Math.floor(Date.now() / 1000);
const timestampNumber = Number(timestamp);

if (!Number.isFinite(timestampNumber)) {
  throw new Error('Timestamp de firma inválido');
}

if (Math.abs(now - timestampNumber) > 300) {
  throw new Error('Firma WACRM demasiado antigua');
}

// n8n entrega el JSON parseado.
// JSON.stringify reproduce el cuerpo que WACRM firmó.
const rawBody = JSON.stringify(body);

const signedPayload = `${timestamp}.${rawBody}`;

const expectedSignature = crypto
  .createHmac('sha256', secret)
  .update(signedPayload, 'utf8')
  .digest('hex');

const receivedBuffer = Buffer.from(receivedSignature, 'hex');
const expectedBuffer = Buffer.from(expectedSignature, 'hex');

if (
  receivedBuffer.length !== expectedBuffer.length ||
  !crypto.timingSafeEqual(receivedBuffer, expectedBuffer)
) {
  throw new Error('Firma WACRM inválida');
}

// Extraer datos útiles para los siguientes nodos
const data = body.data || {};

return [
  {
    json: {
      wacrm_signature_valid: true,
      event: body.event,
      event_id: body.id,
      occurred_at: body.occurred_at,
      account_id: body.account_id,

      conversation_id: data.conversation_id,
      contact_id: data.contact_id,
      whatsapp_message_id: data.whatsapp_message_id,

      content_type: data.content_type,
      message: data.text || null,
    },
  },
];

const contacto = $('Obtener Contacto wacrm').first().json.data;

if (!contacto) {
  throw new Error('WACRM no devolvió los datos del contacto');
}

const conversacion = $('Consultar estado conversación').first().json.data;
const datosEntrada = $('Code - Validar Firma').first().json;

// Números que el bot debe ignorar permanentemente
const numerosExcluidos = [

];

// Normalizar el teléfono para comparar solo dígitos
const telefono = String(contacto.phone || '').replace(/\D/g, '');

const numeroExcluido =
  telefono.length > 0 &&
  numerosExcluidos.includes(telefono);

// Conservar la imagen descargada, si existe
const binarioImagen = $input.first().binary?.imagen;

if (!conversacion) {
  throw new Error('WACRM no devolvió los datos de la conversación');
}

const etiquetas = (contacto.tags || [])
  .map(tag => typeof tag === 'string' ? tag : tag.name)
  .filter(Boolean);

const tieneEtiquetaAsesor = etiquetas.some(
  tag => tag.toLowerCase() === 'requiere asesor'
);

const botPuedeResponder =
  !tieneEtiquetaAsesor && !numeroExcluido;

const resultado = {
  json: {
    phone: contacto.phone,
    name: contacto.name || null,

    message: datosEntrada.message,
    content_type: datosEntrada.content_type,

    conversation_id: datosEntrada.conversation_id,
    contact_id: datosEntrada.contact_id,
    contact_tags: etiquetas,
    whatsapp_message_id: datosEntrada.whatsapp_message_id,

    conversation_status: conversacion.status,
    bot_puede_responder: botPuedeResponder,
    numero_excluido: numeroExcluido,

    wacrm_signature_valid: datosEntrada.wacrm_signature_valid,
  },
};

// Adjuntar la imagen únicamente cuando exista
if (binarioImagen && datosEntrada.content_type === 'image') {
  resultado.binary = {
    imagen: binarioImagen,
  };
}

return [resultado];

const respuesta = $json.output ?? '';
const marcador = '[[TRANSFERIR_ASESOR]]';
const transferir = respuesta.includes(marcador);

return {
  json: {
    ...$json,
    transferir_asesor: transferir,
    respuesta_cliente: respuesta
      .replaceAll(marcador, '')
      .trim(),
  },
};

const contacto = $('Obtener Contacto wacrm').first().json.data;
