if (!contacto?.id) {
  throw new Error('No se encontró el ID del contacto');
}

const etiquetasActuales = (contacto.tags || [])
  .map(tag => typeof tag === 'string' ? tag : tag.name)
  .filter(Boolean);

const etiquetas = etiquetasActuales.filter(
  tag => tag.toLowerCase() !== 'requiere asesor'
);

etiquetas.push('Requiere asesor');

return {
