  },
};

const respuesta = $input.first().json;

const mensajeActual = $('Code - Validar Firma').first().json;
const whatsappMessageId = mensajeActual.whatsapp_message_id;

// Aceptar las estructuras de respuesta habituales de WACRM
let mensajes = respuesta.data;

if (mensajes && !Array.isArray(mensajes) && Array.isArray(mensajes.data)) {
  mensajes = mensajes.data;
}

if (!Array.isArray(mensajes)) {
  throw new Error(
    'La respuesta del historial no contiene un arreglo de mensajes. Revisa la entrada del HTTP Request.'
  );
}

const imagen = mensajes.find(mensaje =>
  mensaje.whatsapp_message_id === whatsappMessageId &&
  mensaje.direction === 'inbound' &&
  mensaje.content_type === 'image' &&
  mensaje.media_url
);

return [
  {
    json: {
      whatsapp_message_id: whatsappMessageId,
      imagen_encontrada: Boolean(imagen),
      media_url: imagen?.media_url || null,
      content_type: mensajeActual.content_type,
      conversation_id: mensajeActual.conversation_id,
      contact_id: mensajeActual.contact_id,
    }
  }
];

